import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ---------- Custom elementwise addition (float) ----------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=["torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"],
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
)

# ---------- Custom Instance Normalization (per-channel) ----------
instance_norm_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void instance_norm_kernel(const float* x, const float* mean, const float* var, float* out, int total_elements) {
    // Each block processes one feature (channel). The grid size is set to the number of features.
    int idx = blockIdx.x; // feature index
    if (idx >= total_elements / 512) return; // dummy guard

    out[idx] = (x[idx] - mean[idx]) / sqrtf(var[idx] + 1e-5f);
}

torch::Tensor instance_norm_cuda(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Number of features
    int num_features = x.size(1);

    float* d_mean = nullptr;
    float* d_var = nullptr;
    cudaMalloc(&d_mean, num_features * sizeof(float));
    cudaMalloc(&d_var, num_features * sizeof(float));

    instance_norm_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), d_mean, d_var, out.data_ptr<float>(), size);

    cudaDeviceSynchronize();

    cudaFree(d_mean);
    cudaFree(d_var);

    return out;
}
"""

element_norm_source = """
torch::Tensor instance_norm_cuda(torch::Tensor x) {
