    cudaMalloc(&d_mean, num_features * sizeof(float));
    cudaMalloc(&d_var, num_features * sizeof(float));

    instance_norm_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), d_mean, d_var, out.data_ptr<float>(), size);

    cudaDeviceSynchronize();

