"""

instance_norm_cuda = load_inline(
    name="instance_norm_cuda",
    cpp_sources=["torch::Tensor instance_norm_cuda(torch::Tensor x);"],
    cuda_sources=element_norm_source,
    functions=["instance_norm_cuda"],
    verbose=True,
