class ModelNew(nn.Module):
    def __init__(self, num_features: int = 64):
        super().__init__()
        self.elementwise_add = elementwise_add
        # InstanceNorm2d expects input shape (batch, features, H, W). Our custom operator handles that.
        self.instance_norm_cuda = instance_norm_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.instance_norm_cuda(x)
